  merge into admin.cfg_api_contrato c
  using (select 'v1' as versao from dual) s
     on (c.versao = s.versao)
   when matched then update set c.conteudo = l_doc
   when not matched then insert (versao, conteudo) values (s.versao, l_doc);
  commit;
end;
/

select versao, dbms_lob.getlength(conteudo) as tamanho,
       json_value(conteudo, '$.info.title') as titulo,
       json_value(conteudo, '$.paths."/categorias".get.summary') as exemplo_acento
  from admin.cfg_api_contrato;
